function createHighSchoolPlayingTimeOpportunity(options = {}) {
  if (typeof PlayingTimeGameExposure === "undefined") return null;
  const requestedPosition = options.requestedPosition || player.primaryPosition || "內野手";
  const school = getHighSchoolPlayingTimeSchoolContext(player);
  const readinessSnapshot = createHighSchoolOpportunityReadinessSnapshot(requestedPosition, player);
  const opportunityIndex = Math.max(1, Number(options.opportunityIndex) || 1);
  const schoolYearIdentity = player.schoolInvitationState?.selectedSchoolYearRosterIdentity?.identity
    || `${school.schoolId}|legacy-high-school-year-one`;
  const highSchoolYear = Math.max(1, Math.min(3, Math.floor(Number(options.highSchoolYear) || 1)));
  const yearPhase = highSchoolYear === 1 ? "high-school-year-one" : `high-school-year-${highSchoolYear}`;
  const opportunityPhase = options.opportunityPhase || (opportunityIndex === 1 ? "autumn-exhibition" : "post-autumn-evaluation");
  const resolved = PlayingTimeGameExposure.resolveStartingOpportunity({
    matchId: options.matchId,
    readinessSnapshot,
    opportunitySeed: [player.capabilityState?.settlementId || player.capabilityState?.version || "capability", schoolYearIdentity, yearPhase, opportunityPhase, opportunityIndex, options.matchId || "match"].join("|"),
    actualRole: options.actualRole,
    projectedRole: school.projectedRole,
    playingTimeEnvironment: school.playingTimeEnvironment,
    competitionDepth: school.competitionDepth,
    positionNeed: school.positionNeed,
    coachUsageStyle: school.coachStyle,
    evaluationTrend: options.evaluationTrend,
    previousActualExposure: options.previousActualExposure,
    coachTrust: options.includeDynamicReadiness ? player.relationships?.coachTrust : undefined,
    health: options.includeDynamicReadiness ? player.body : undefined,
    stableVariationSeed: options.stableVariationSeed,
    directStartForced: options.directStartForced === true,
    gameContext: { gameType: "highSchoolExhibition", inning: 0, expectedGameImportance: "regular", importance: "regular", leverage: "normal", scoreMargin: 0 }
  });
  if (!options.preserveDecisionId) return resolved;
  return Object.freeze({
    ...cloneSchoolInvitationValue(resolved),
    decisionId: options.preserveDecisionId,
    opportunitySeed: options.preserveOpportunitySeed || resolved.opportunitySeed
  });
}

function materializeSelectedHighSchoolRoster(subject = player, options = {}) {
  if (typeof HighSchoolEntryRosterContext === "undefined" || typeof TeamRosterFoundation === "undefined") return null;
  const state = subject?.schoolInvitationState;
  const invitation = getSelectedSchoolInvitation(subject);
  const baseRoster = state?.selectedBaseRoster || invitation?.baseRoster;
  if (!baseRoster || !TeamRosterFoundation.validateRoster(baseRoster).ok) return null;
  const invitationPosition = invitation?.positionCompetitionContext?.position || invitation?.schoolInterest?.candidatePosition || "";
  const rawPosition = options.playerPosition || subject?.primaryPosition || invitationPosition;
  const normalizedRequested = TeamRosterFoundation.normalizePosition(rawPosition);
  const requestedPosition = ["內野手", "外野手"].includes(rawPosition) && invitationPosition
    ? TeamRosterFoundation.normalizePosition(invitationPosition) : normalizedRequested;
  const rosterRole = options.rosterRole === "starter" ? "starter" : "bench";
  const selectedRoster = HighSchoolEntryRosterContext.injectPlayerIntoSelectedRoster(
    baseRoster,
    createHighSchoolRosterPlayerActor(subject, requestedPosition),
    { playerRole: rosterRole, playerPosition: requestedPosition }
  );
  const playerCapability = HighSchoolEntryRosterContext.getPositionCapability(
    selectedRoster.players.find(actor => actor.id === "player"), requestedPosition
  );
  const invitationCompetition = invitation?.positionCompetitionContext;
  const competition = options.refreshCompetition !== true && invitationCompetition?.position === requestedPosition
    ? cloneSchoolInvitationValue(invitationCompetition)
    : HighSchoolEntryRosterContext.deriveCompetitionContext(baseRoster, requestedPosition, playerCapability);
  const activeRosterIdentity = state.selectedSchoolYearRosterIdentity || invitation.schoolYearRosterIdentity;
  state.selectedSchoolYearRosterIdentity = cloneSchoolInvitationValue(activeRosterIdentity);
  state.selectedBaseRoster = cloneSchoolInvitationValue(baseRoster);
  state.selectedSchoolRoster = cloneSchoolInvitationValue(selectedRoster);
  state.selectedPositionCompetitionContext = cloneSchoolInvitationValue(competition);
  state.selectedPlayerInjectionState = {
    ...cloneSchoolInvitationValue(selectedRoster.playerInjection),
    status: "injected",
    schoolYearRosterIdentity: activeRosterIdentity.identity
  };
  return selectedRoster;
}

function createHighSchoolMatchSimulationRoster(role, playerPosition, simulationSeed = 1, selectedHomeRoster = null, opponentIdentity = "regional-power-school") {
  if (typeof TeamRosterFoundation === "undefined" || typeof TeamStrengthModel === "undefined") {
    return createLegacyHighSchoolMatchSimulationRoster(role, playerPosition);
  }
  const selectedSchool = getSelectedHighSchoolContext(player);
  const playerRole = role === "starter" ? "starter" : "bench";
  const playerActor = createHighSchoolRosterPlayerActor(player, playerPosition);
  const homeRoster = selectedHomeRoster && TeamRosterFoundation.validateRoster(selectedHomeRoster).ok
    ? selectedHomeRoster
    : TeamRosterFoundation.generateTeamRoster({
      teamId: selectedSchool?.schoolId || "home-school", schoolId: selectedSchool?.schoolId || "home-school",
      schoolStandard: selectedSchool?.schoolTier || "standard", yearIdentity: `hs-y1-${player.age || 15}`,
      seed: `${simulationSeed}|home`, playerActor, playerRole, playerPosition
    });
  const awayRoster = TeamRosterFoundation.generateTeamRoster({
    teamId: opponentIdentity, schoolId: opponentIdentity, schoolStandard: "competitive",
    yearIdentity: `hs-y1-${player.age || 15}`, seed: `${simulationSeed}|away`
  });
  const homeStrength = TeamStrengthModel.deriveTeamStrengthProfile(homeRoster);
  const awayStrength = TeamStrengthModel.deriveTeamStrengthProfile(awayRoster);
  return {
    home: TeamRosterFoundation.toMatchRoster(homeRoster, homeStrength),
    away: TeamRosterFoundation.toMatchRoster(awayRoster, awayStrength)
  };
}

function insertPlayerIntoHighSchoolMatchLineup(match) {
  const lineup = match.rosters?.[getHighSchoolPlayerTeamSide(match)]?.lineup;
  const bench = match.rosters?.[getHighSchoolPlayerTeamSide(match)]?.bench;
  if (typeof TeamRosterFoundation !== "undefined") TeamRosterFoundation.assertActiveDefense(match.rosters?.[getHighSchoolPlayerTeamSide(match)]);
  if (!Array.isArray(lineup)) return false;
  const existingSlot = lineup.findIndex(item => item.id === "player");
  if (existingSlot >= 0) {
    match.playerLineupSlot = existingSlot;
    return false;
  }
  const slot = Math.max(0, Math.min(8, Number(match.battingOrderIndex?.[getHighSchoolPlayerTeamSide(match)]) || 0));
  const replaced = lineup[slot];
  const assignedPosition = match.gameExposureState?.opportunitySnapshot?.assignedPosition
    || match.developmentPositionOverride || match.playerFieldingAssignment || match.position;
  const incumbent = getCurrentHighSchoolMatchDefender(match, getHighSchoolPlayerTeamSide(match), assignedPosition);
  if (!incumbent) throw new Error("Active defense integrity failed: missing substitution incumbent");
  if (incumbent !== replaced) return false;
  const benchPlayer = (bench || []).find(item => item.id === "player");
  if (!benchPlayer) throw new Error("Active defense integrity failed: incoming player not on bench");
  const incoming = { ...benchPlayer, id: "player", name: player.name || "你",
    position: replaced.position, defensivePosition: replaced.defensivePosition,
    bats: player.bats, throws: player.throws, age: player.age, source: "canonical-player" };
  const nextRoster = { ...match.rosters[getHighSchoolPlayerTeamSide(match)], lineup: lineup.map((actor, index) => index === slot ? incoming : actor),
    bench: [...(bench || []).filter(item => item.id !== "player"), replaced] };
  if (typeof TeamRosterFoundation !== "undefined") TeamRosterFoundation.assertActiveDefense(nextRoster);
  match.rosters[getHighSchoolPlayerTeamSide(match)] = nextRoster;
  match.playerLineupSlot = slot;
  return { slot, replaced };
}

function shouldEnterHighSchoolMatchPlayer(match) {
  if (match && !match.playerEntryCompleted && match.playerLineupStatus === "bench") {
    const assignedPosition = match.gameExposureState?.opportunitySnapshot?.assignedPosition
      || match.developmentPositionOverride || match.playerFieldingAssignment || match.position;
    const incumbent = getCurrentHighSchoolMatchDefender(match, getHighSchoolPlayerTeamSide(match), assignedPosition);
    if (!incumbent) throw new Error("Active defense integrity failed: missing substitution incumbent");
    if (match.rosters[getHighSchoolPlayerTeamSide(match)].lineup[Number(match.battingOrderIndex?.[getHighSchoolPlayerTeamSide(match)]) || 0] !== incumbent) return false;
  }
  const exposureState = match?.gameExposureState;
  if (exposureState) {
    if (exposureState.pitcherExposureDeferred || exposureState.plannedUsage?.appearanceType === "noAppearance") return false;
    const opportunity = exposureState.opportunitySnapshot || {};
    const margin = Math.abs(getHighSchoolPlayerScoreDifference(match));
    const coachStyle = opportunity.coachUsageStyle || "balanced";
    const actualRole = opportunity.actualRole || match.role || "bench";
    const contextAllowsEntry = coachStyle === "developmental"
      || actualRole === "starter"
      || (coachStyle === "conservative" ? margin >= 3 : coachStyle === "performanceFirst" ? actualRole === "rotation" || margin <= 2 : actualRole === "rotation" || margin >= 2);
    if (!contextAllowsEntry || match.inning < 5) return false;
  }
  return Boolean(match && !match.playerEntryCompleted && match.playerLineupStatus === "bench"
    && match.offenseTeam === getHighSchoolPlayerTeamSide(match)
    && match.inning >= Math.max(1, Number(match.playerEntryWindowInning) || 1)
    && match.outs < 3);
}

function enterHighSchoolMatchPlayer(match) {
  assertHighSchoolMatchCapabilityAdmission(player);
  if (!shouldEnterHighSchoolMatchPlayer(match)) return false;
  const entryTruth = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const insertion = insertPlayerIntoHighSchoolMatchLineup(match);
  if (!insertion) return false;
  match.playerLineupStatus = "substitute";
  match.playerEntryCompleted = true;
  match.playerFieldingAssignment = match.gameExposureState?.opportunitySnapshot?.assignedPosition || match.developmentPositionOverride || match.position;
  match.currentFieldingPosition = match.playerFieldingAssignment;
  match.currentBatter = "player";
  const plannedAppearance = match.gameExposureState?.plannedUsage?.appearanceType || "lateGameAppearance";
  const entryLabel = !match.gameExposureState ? "叫你代打"
    : plannedAppearance === "defensiveSubstitution" ? "準備接替守備，並先從這個打席進入比賽"
    : plannedAppearance === "pinchHit" ? "叫你代打" : "叫你進入比賽";
  match.matchEntryHistory = `${match.inning}局${match.half}${match.outs}出局時，教練${entryLabel}；進場比分與壘況沿用當下比賽。`;
  match.currentAssignment = `${formatHighSchoolMatchRunners(match.runners)}、${match.outs} 出局；你從板凳進入第 ${insertion.slot + 1} 棒。`;
  setHighSchoolCoachTacticalDirection(match);
  const event = recordHighSchoolMatchSimulationEvent(match, {
    type: "playerEntry", inning: entryTruth.inning, half: entryTruth.half,
    lineupSlot: insertion.slot, replacedPlayerId: insertion.replaced?.id || "", plannedAppearanceType: plannedAppearance,
    assignment: match.currentAssignment, outs: entryTruth.outs, scores: entryTruth.scores, runners: entryTruth.runners
  });
  recordHighSchoolMatchOpportunityCheckpoint("player-entry", match, {
    lineupSlot: insertion.slot,
    entry: { inning: entryTruth.inning, half: entryTruth.half, outs: entryTruth.outs, scores: entryTruth.scores, runners: entryTruth.runners }
  });
  return event;
}

function resolveStartingOpportunity(input = {}) {
  const readiness = input.readinessSnapshot;
  if (!readiness || readiness.version !== READINESS_VERSION) {
    throw new Error("Playing-Time Opportunity requires a valid Opportunity Readiness Snapshot.");
  }
  const matchId = String(input.matchId || "match");
  const playerId = String(readiness.playerId || "player");
  const actualRole = normalizeActualRole(input.actualRole);
  const coachUsageStyle = normalizeCoachUsageStyle(input.coachUsageStyle || input.coachStyle);
  const positionCapability = clamp(readiness.positionReadiness, 0, 10, 5);
  const positionFit = clamp(readiness.positionFit, 0, 10, 5);
  const positionExperience = clamp(readiness.experienceReadiness, 0, 10, 5);
  const position = {
    requested: normalizePosition(readiness.requestedPosition),
    assigned: normalizePosition(readiness.position),
    legal: readiness.positionLegal === true,
    pitcherExposureDeferred: readiness.pitcherExposureDeferred === true,
    fallbackApplied: readiness.positionFallbackApplied === true
  };
  const directStartForced = input.directStartForced === true;
  const gameContext = input.gameContext || {};
  const previousActualExposure = input.previousActualExposure ? {
    appearanceType: input.previousActualExposure.appearanceType || "noAppearance",
    plateAppearances: Math.max(0, Number(input.previousActualExposure.plateAppearances) || 0),
    defensiveInnings: Math.max(0, Number(input.previousActualExposure.defensiveInnings) || 0)
  } : null;
  const evaluationTrend = clamp(input.evaluationTrend, -4, 4, 0);
  const coachTrust = input.coachTrust === undefined ? null : clamp(input.coachTrust, 0, 10, 5);
  const health = input.health && typeof input.health === "object" ? input.health : null;
  const healthReadiness = health
    ? -Math.round(clamp(health.fatigue, 0, 20, 0) * 0.45 + clamp(health.pain, 0, 20, 0) * 0.8 + clamp(health.injuryRisk, 0, 20, 0) * 0.35)
    : null;
  const decisionIdentityParts = [OPPORTUNITY_VERSION, matchId, playerId, input.opportunitySeed || "", actualRole,
    input.projectedRole || "", input.playingTimeEnvironment || "medium", input.competitionDepth || "medium",
    input.positionNeed || "medium", coachUsageStyle, position.assigned, positionCapability, positionFit, positionExperience,
    gameContext.gameType || "game", gameContext.inning || 0, gameContext.scoreMargin || 0,
    gameContext.expectedGameImportance || gameContext.importance || "regular", gameContext.leverage || "normal"];
  if (input.evaluationTrend !== undefined) decisionIdentityParts.push(evaluationTrend);
  if (coachTrust !== null) decisionIdentityParts.push(coachTrust);
  if (healthReadiness !== null) decisionIdentityParts.push(healthReadiness);
  if (previousActualExposure) decisionIdentityParts.push([previousActualExposure.appearanceType, previousActualExposure.plateAppearances, previousActualExposure.defensiveInnings].join(":"));
  const decisionIdentity = decisionIdentityParts.join("|");
  const opportunityHash = stableHash(input.stableVariationSeed || decisionIdentity);
  const hashVariation = (opportunityHash % 31) - 15;
  const scoreBreakdown = {
    actualRole: ROLE_BASE[actualRole],
    positionCapability: Math.round((positionCapability - 5) * 4),
    positionFit: Math.round((positionFit - 5) * 2),
    positionExperience: Math.round((positionExperience - 5) * 1.5),
    schoolEnvironment: ENVIRONMENT_MODIFIER[input.playingTimeEnvironment] ?? ENVIRONMENT_MODIFIER.medium,
    competitionDepth: COMPETITION_MODIFIER[input.competitionDepth] ?? COMPETITION_MODIFIER.medium,
    positionNeed: POSITION_NEED_MODIFIER[input.positionNeed] ?? POSITION_NEED_MODIFIER.medium,
    projectedRolePrior: PROJECTED_ROLE_PRIOR[input.projectedRole] ?? 0,
    coachUsage: deriveCoachModifier(coachUsageStyle, actualRole, positionCapability),
    gameContext: deriveGameContextModifier(gameContext),
    deterministicVariation: hashVariation
  };
  if (input.evaluationTrend !== undefined) scoreBreakdown.evaluationTrend = Math.round(evaluationTrend);
  if (coachTrust !== null) scoreBreakdown.coachTrust = Math.round((coachTrust - 5) * 1.5);
  if (healthReadiness !== null) scoreBreakdown.healthReadiness = healthReadiness;
  const opportunityScore = Object.values(scoreBreakdown).reduce((sum, value) => sum + Number(value || 0), 0);
  let plannedUsage = resolvePlannedAppearance(opportunityScore, actualRole, coachUsageStyle, opportunityHash);
  let exposureSource = "opportunity-resolver";
  if (directStartForced && !position.pitcherExposureDeferred) {
    plannedUsage = { appearanceType: "start", entryInning: 1, entryHalf: "上" };
    exposureSource = "direct-start-forced";
  }
  if (position.pitcherExposureDeferred || !position.legal) plannedUsage = { appearanceType: "noAppearance", entryInning: null, entryHalf: "" };
  const reasons = [
    `actual-role:${actualRole}`,
    `school-environment:${input.playingTimeEnvironment || "medium"}`,
    `competition-depth:${input.competitionDepth || "medium"}`,
    `position-need:${input.positionNeed || "medium"}`,
    `coach-usage:${coachUsageStyle}`,
    position.fallbackApplied ? `legal-position-fallback:${position.assigned}` : "position-legal"
  ];
  if (position.pitcherExposureDeferred) reasons.push("pitcher-exposure-deferred");
  if (!position.legal) reasons.push("position-illegal");
  const startingOpportunity = plannedUsage.appearanceType === "start" ? "start" : actualRole === "rotation" ? "rotationCandidate" : "bench";
  return deepFreeze({
    version: OPPORTUNITY_VERSION,
    sourceVersion: OPPORTUNITY_VERSION,
    decisionId: `${matchId}|${playerId}|${opportunityHash.toString(16).padStart(8, "0")}`,
    matchId,
    playerId,
    exposureSource,
    actualRole,
    actualRoleAtDecision: actualRole,
    projectedRolePrior: input.projectedRole || "",
    playingTimeEnvironment: input.playingTimeEnvironment || "medium",
    schoolPlayingTimeEnvironment: input.playingTimeEnvironment || "medium",
    competitionDepth: input.competitionDepth || "medium",
    positionCompetition: input.competitionDepth || "medium",
    positionNeed: input.positionNeed || "medium",
    evaluationTrend,
    previousActualExposure,
    coachUsageStyle,
    positionCapability,
    positionFit,
    positionExperience,
    assignedPosition: position.assigned,
    requestedPosition: position.requested,
    positionFallbackApplied: position.fallbackApplied,
    assignmentSource: readiness.assignmentSource || (position.fallbackApplied ? "position-fallback" : "requested-position"),
    assignmentReason: readiness.assignmentReason || (position.fallbackApplied ? `legal-position-fallback:${position.assigned}` : "specific-position-request"),
    pitcherExposureDeferred: position.pitcherExposureDeferred,
    startingOpportunity,
    startingDecision: startingOpportunity,
    appearancePlan: plannedUsage,
    substitutionOpportunity: plannedUsage.appearanceType === "start" ? "none" : plannedUsage.appearanceType,
    opportunityReasons: reasons,
    opportunitySeed: decisionIdentity,
    gameContext: clone(gameContext),
    readinessSnapshot: clone(readiness),
    plannedUsage,
    debug: { opportunityHash, opportunityScore, scoreBreakdown, reasons }
  });
}

function classifyHighSchoolOffensiveOpportunity(match, choices = buildOffensiveDecisionChoices(match)) {
  const inning = Math.max(1, Math.floor(Number(match?.inning) || 1));
  const regulationInnings = Math.max(1, Math.floor(Number(match?.regulationInnings) || 7));
  const half = match?.half === "上" ? "上" : "下";
  const outs = Math.max(0, Math.min(2, Math.floor(Number(match?.outs) || 0)));
  const runners = (match?.runners || []).slice(0, 3);
  while (runners.length < 3) runners.push(null);
  const runnerCount = runners.filter(Boolean).length;
  const scoringPosition = Boolean(runners[1] || runners[2]);
  const scoreDifference = getHighSchoolPlayerScoreDifference(match);
  const deficit = Math.max(0, -scoreDifference);
  const finalInningBottom = inning >= regulationInnings && half === "下";
  const finalPlayerOffense = inning >= regulationInnings && half === (getHighSchoolPlayerTeamSide(match) === "home" ? "下" : "上");
  const lateGame = inning >= Math.max(5, regulationInnings - 1);
  const gameLive = !match?.completed && !match?.pendingGameSettlement && outs < 3;
  const canTieOrLead = deficit > 0 && deficit <= runnerCount + 1;
  const approachCommitments = [...new Set((choices || []).map(choice => `${choice.selectionProfile || ""}|${choice.swingIntent || ""}`).filter(value => value !== "|"))];
  const strategicObjectives = [...new Set((choices || []).map(choice => choice.objective).filter(Boolean))];
  const distinctTradeoffs = approachCommitments.length >= 2 && strategicObjectives.length >= 2;
  let leverageClass = "routine";
  let reason = "routine-game-state";
  if (gameLive && finalPlayerOffense && canTieOrLead && (scoringPosition || outs === 2)) {
    leverageClass = "critical";
    reason = "final-inning-tying-or-go-ahead-run";
  } else if (gameLive && finalPlayerOffense && deficit > 0 && deficit <= 3) {
    leverageClass = "highLeverage";
    reason = scoringPosition ? "late-run-scoring-pressure" : "late-game-on-base-relevance";
  } else if (gameLive && lateGame && Math.abs(scoreDifference) <= 2 && (scoreDifference <= 0 || scoringPosition || runnerCount > 0)) {
    leverageClass = "meaningful";
    reason = "close-late-game-context";
  } else if (gameLive && scoringPosition && Math.abs(scoreDifference) <= 3) {
    leverageClass = "meaningful";
    reason = "run-scoring-opportunity";
  }
  const scoreBand = scoreDifference <= -4 ? "large-deficit" : scoreDifference < 0 ? "trailing-close"
    : scoreDifference === 0 ? "tied" : scoreDifference >= 4 ? "large-lead" : "leading-close";
  const topology = runners.map(Boolean).map(Number).join("");
  const situationFamily = `${lateGame ? "late" : "early"}|${scoreBand}|${outs}|${topology}|${leverageClass}`;
  return Object.freeze({
    version: "offensive-opportunity-v1",
    leverageClass,
    reason,
    meaningfulCandidate: gameLive && leverageClass !== "routine" && distinctTradeoffs,
    gameLive,
    inning,
    half,
    outs,
    runners: Object.freeze(runners),
    runnerCount,
    scoringPosition,
    scoreDifference,
    deficit,
    finalInningBottom,
    lateGame,
    canTieOrLead,
    distinctTradeoffs,
    approachCommitments: Object.freeze(approachCommitments),
    strategicObjectives: Object.freeze(strategicObjectives),
    situationFamily,
    noveltyKey: situationFamily,
    playerPANumber: getHighSchoolOffensivePlayerPANumber(match)
  });
}

function resolveHighSchoolOffensiveDecision(match, choice, tier, options = {}) {
  if (!choice || choice.matchMomentId !== getHighSchoolYearOneMomentId(match) || !isOffensiveDecisionChoiceLegal(choice, match)) return false;
  const plateAppearanceState = resolveHighSchoolOffensivePlateAppearance(match, choice, options.plateAppearance || {});
  if (!plateAppearanceState?.completed || !plateAppearanceState.result || plateAppearanceState.resultApplied) return false;
  const result = plateAppearanceState.result;
  settleHighSchoolPitcherRuntimeAfterPlateAppearance(match, plateAppearanceState);
  const resolvedTier = plateAppearanceState.executionQuality === "strong" ? "strong"
    : plateAppearanceState.executionQuality === "weak" ? "failure" : "mixed";
  const situationBefore = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const scoresBefore = { ...match.scores };
  const runnerFacts = applyHighSchoolSimulatedPlateAppearance(match, result, "player", getHighSchoolPlayerTeamSide(match));
  advanceHighSchoolMatchBattingOrder(match, getHighSchoolPlayerTeamSide(match));
  match.playerContribution.runsCreated += match.scores[getHighSchoolPlayerTeamSide(match)] - scoresBefore[getHighSchoolPlayerTeamSide(match)];
  if (["single", "double", "triple", "homeRun"].includes(result)) match.playerContribution.hits += 1;
  if (result === "walk") match.playerContribution.walks += 1;
  const situationAfter = { inning: match.inning, half: match.half, outs: match.outs, scores: { ...match.scores }, runners: match.runners.slice() };
  const baseballMeaning = deriveHighSchoolOffensiveBaseballMeaning({
    before: situationBefore,
    after: situationAfter,
    paResult: result,
    runnerChanges: runnerFacts.runnerChanges,
    scoringRunnerIds: runnerFacts.scoringRunnerIds
  });
  const playerFacingResult = formatHighSchoolOffensivePlayerFacingResult(choice, result, baseballMeaning, plateAppearanceState);
  const executionText = formatHighSchoolOffensiveExecutionText(choice, plateAppearanceState);
  const coachFeedback = formatHighSchoolOffensiveCoachFeedback(choice, plateAppearanceState);
  const objectiveSucceeded = didHighSchoolOffensiveObjectiveSucceed(choice, result, baseballMeaning);
  const plateAppearanceEvent = recordHighSchoolMeaningfulPlateAppearance(match, "player", result, situationBefore, situationAfter, match.scores[getHighSchoolPlayerTeamSide(match)] - scoresBefore[getHighSchoolPlayerTeamSide(match)], runnerFacts);
  Object.assign(plateAppearanceEvent, {
    objective: choice.objective,
    approach: choice.approach,
    selectionProfile: choice.selectionProfile,
    swingIntent: choice.swingIntent,
    route: choice.route,
    riskProfile: choice.riskProfile,
    objectiveSucceeded,
    decisionQuality: plateAppearanceState.decisionQuality,
    executionQuality: plateAppearanceState.executionQuality,
    recognitionSummary: JSON.parse(JSON.stringify(plateAppearanceState.recognitionSummary)),
    swingExecutionSummary: JSON.parse(JSON.stringify(plateAppearanceState.swingExecutionSummary)),
    pitchCount: plateAppearanceState.pitchNumber,
    battedBallPhysicalTruth: plateAppearanceState.battedBallPhysicalTruth ? JSON.parse(JSON.stringify(plateAppearanceState.battedBallPhysicalTruth)) : null,
    physicalOutcomeFlow: plateAppearanceState.officialBallInPlayOutcome?.authority === "physicalOutcomeMappingV1" ? "physicalTruthToOfficialOutcome" : plateAppearanceState.officialBallInPlayOutcome?.authority === "legacyCompatibilityFallback" ? "legacyCompatibilityFallback" : plateAppearanceState.battedBallPhysicalTruth ? "physicalTruthToLegacyDownstreamOutcome" : "notBallInPlay",
    officialBallInPlayOutcome: plateAppearanceState.officialBallInPlayOutcome ? JSON.parse(JSON.stringify(plateAppearanceState.officialBallInPlayOutcome)) : null,
    coachFeedback,
    primaryCause: result === "walk" ? "countAccumulation" : result === "strikeout" ? "strikeAccumulation" : "contactExecution",
    secondaryCause: "",
    responsibleActor: "player"
  });
  recordHighSchoolYearOneMoment(match, choice.matchDecision, resolvedTier, playerFacingResult.outcome, playerFacingResult.consequence, situationAfter, {
    runnerChanges: runnerFacts.runnerChanges,
    scoringRunnerIds: runnerFacts.scoringRunnerIds,
    thirdOutResolution: runnerFacts.thirdOutResolution,
    resultCode: result
  });
  const completedMoment = match.completedMoments.at(-1);
  Object.assign(completedMoment, {
    objective: choice.objective,
    approach: choice.approach,
    selectionProfile: choice.selectionProfile,
    swingIntent: choice.swingIntent,
    action: choice.action,
    route: choice.route,
    riskProfile: choice.riskProfile,
    requirements: choice.requirements.slice(),
    executionOnly: choice.executionOnly,
    resultCode: result,
    objectiveSucceeded,
    runnerChanges: runnerFacts.runnerChanges.map(change => ({ ...change })),
    scoringRunnerIds: runnerFacts.scoringRunnerIds.slice(),
    baseballMeaning,
    decisionQuality: plateAppearanceState.decisionQuality,
    executionQuality: plateAppearanceState.executionQuality,
    recognitionSummary: JSON.parse(JSON.stringify(plateAppearanceState.recognitionSummary)),
    swingExecutionSummary: JSON.parse(JSON.stringify(plateAppearanceState.swingExecutionSummary)),
    pitchCount: plateAppearanceState.pitchNumber,
    pitchHistory: JSON.parse(JSON.stringify(plateAppearanceState.pitchHistory)),
    battedBallPhysicalTruth: plateAppearanceState.battedBallPhysicalTruth ? JSON.parse(JSON.stringify(plateAppearanceState.battedBallPhysicalTruth)) : null,
    batterAnticipation: plateAppearanceState.batterAnticipation ? JSON.parse(JSON.stringify(plateAppearanceState.batterAnticipation)) : null,
    executionText,
    coachFeedback,
    primaryCause: result === "walk" ? "countAccumulation" : result === "strikeout" ? "strikeAccumulation" : "contactExecution",
    secondaryCause: "",
    responsibleActor: "player"
  });
  match.lastOffensiveResolution = {
    objective: choice.objective,
    approach: choice.approach,
    selectionProfile: choice.selectionProfile,
    swingIntent: choice.swingIntent,
    route: choice.route,
    resultCode: result,
    objectiveSucceeded,
    baseballMeaning,
    before: situationBefore,
    after: situationAfter,
    balls: plateAppearanceState.balls,
    strikes: plateAppearanceState.strikes,
    pitchNumber: plateAppearanceState.pitchNumber,
    pitchHistory: JSON.parse(JSON.stringify(plateAppearanceState.pitchHistory)),
    battedBallPhysicalTruth: plateAppearanceState.battedBallPhysicalTruth ? JSON.parse(JSON.stringify(plateAppearanceState.battedBallPhysicalTruth)) : null,
    physicalOutcomeFlow: plateAppearanceState.officialBallInPlayOutcome?.authority === "physicalOutcomeMappingV1" ? "physicalTruthToOfficialOutcome" : plateAppearanceState.officialBallInPlayOutcome?.authority === "legacyCompatibilityFallback" ? "legacyCompatibilityFallback" : plateAppearanceState.battedBallPhysicalTruth ? "physicalTruthToLegacyDownstreamOutcome" : "notBallInPlay",
    officialBallInPlayOutcome: plateAppearanceState.officialBallInPlayOutcome ? JSON.parse(JSON.stringify(plateAppearanceState.officialBallInPlayOutcome)) : null,
    batterAnticipation: plateAppearanceState.batterAnticipation ? JSON.parse(JSON.stringify(plateAppearanceState.batterAnticipation)) : null,
    recognitionSummary: JSON.parse(JSON.stringify(plateAppearanceState.recognitionSummary)),
    swingExecutionSummary: JSON.parse(JSON.stringify(plateAppearanceState.swingExecutionSummary)),
    decisionQuality: plateAppearanceState.decisionQuality,
    executionQuality: plateAppearanceState.executionQuality,
    coachFeedback
  };
  match.offensivePlateAppearanceState = JSON.parse(JSON.stringify(OffensivePlateApproach.markResultApplied(plateAppearanceState)));
  if (match.pendingOffensiveOpportunity) {
    match.pendingOffensiveOpportunity.status = "resolved";
    match.pendingOffensiveOpportunity.result = result;
    match.pendingOffensiveOpportunity.resultApplied = true;
  }
  if (match.offensivePlayerAgencyState?.selection === "manual"
    && match.offensivePlayerAgencyState.canonicalPAIdentity === plateAppearanceState.paIdentity) {
    match.offensivePlayerAgencyState.status = "resolved";
    match.offensivePlayerAgencyState.result = result;
    match.offensivePlayerAgencyState.resultApplied = true;
    const traceAgency = [...(match.opportunityDebugTrace?.opportunities || [])].reverse().find(item => item.agencyOpportunityCandidate
      && item.playerPANumber === match.offensivePlayerAgencyState.playerPANumber && item.agencySelection === "manual");
    if (traceAgency) {
      traceAgency.agencyResolved = true;
      traceAgency.result = result;
    }
  }
  assertHighSchoolMatchStateIntegrity(match, options.integrityLabel || "player-offense-decision");
  match.simulationPhase = options.resolvedPhase || "moment_1_resolved";
  match.currentAssignment = options.assignment || "等待隊友完成這個半局。";
  match.coachReaction = coachFeedback;
  match.teamReaction = match.playerRunnerLocation >= 0 ? "你留在壘上，後續棒次開始接手。" : "後續棒次走進打擊區，比賽沒有因你的結果停止。";
  return completedMoment;
}

function settleHighSchoolYearOneMatch(match, finalDecision) {
  if (match.settled || match.completed) return false;
  const contribution = match.playerContribution;
  const finalMoment = match.completedMoments.at(-1);
  if (finalMoment) {
    finalMoment.scores = { ...match.scores };
    finalMoment.runners = [null, null, null];
    finalMoment.outs = 3;
    finalMoment.half = "終";
  }
  const resultLabel = getHighSchoolPlayerScoreDifference(match) > 0 ? "球隊勝利" : getHighSchoolPlayerScoreDifference(match) < 0 ? "球隊落敗" : "球隊和局";
  match.teamResult = `${resultLabel}，終場 ${match.scores[getHighSchoolPlayerTeamSide(match)]}：${match.scores[getHighSchoolOpponentTeamSide(match)]}`;
  const momentCount = match.completedMoments.length;
  const participationTruth = deriveHighSchoolMatchActualExposure(match);
  const overallTier = contribution.strong > contribution.failure ? "strong" : contribution.failure > contribution.strong ? "failure" : "mixed";
  const countLabel = momentCount === 1 ? "一個" : momentCount === 2 ? "兩個" : momentCount === 3 ? "三個" : `${momentCount} 個`;
  const performanceLines = match.completedMoments.map((moment, index) => `第${["一", "二", "三"][index] || index + 1}次：${moment.outcome}。`).join(" ");
  match.performanceSummary = participationTruth.participated
    ? `本場${countLabel}關鍵時刻：${performanceLines || "你依照角色完成了這場比賽。"}`
    : "本場比賽完整結束，但教練沒有把你換上場；沒有虛構守備局數、打席或比賽成長。";
  match.outcome = `${match.teamResult}。${match.performanceSummary}`;
  match.coachReaction = overallTier === "strong"
    ? "「今天幾次輪到你，你都把眼前的球處理清楚。下一場繼續照這個節奏準備。」"
    : overallTier === "mixed"
      ? "「有幾球你看對了，也有一步慢了。下一輪把判斷後的第一個動作做得更乾淨。」"
      : "「你不是沒看懂，動作只是慢了一步。下一輪先把接球到出手的節奏修掉。」";
  match.consequence = overallTier === "strong"
    ? "下一場實戰名單仍會保留你的名字。"
    : overallTier === "mixed"
      ? "接下來的訓練會更重視判斷後的第一步動作。"
      : "下一輪訓練會先練接球、轉身與出手之間的銜接。";
  match.teamReaction = match.teamResult;
  match.passage = "終場哨響，記分板停在這場比賽真正結束的局數。";
  match.momentIndex = momentCount;
  match.currentMomentId = "";
  match.currentDomain = "complete";
  match.simulationPhase = "complete";
  match.currentAssignment = "比賽已結束。";
  match.completed = true;
  match.settled = true;
  setHighSchoolCoachTacticalDirection(match);
  recordHighSchoolMatchSimulationEvent(match, {
    type: "gameEnd", inning: match.inning, half: "終", scores: match.scores
  });
  finalizeHighSchoolGameRecord(match);
  finalizeHighSchoolGameExposure(match);
  if (typeof MatchExperienceDevelopment !== "undefined") {
    const finalizedExposure = match.gameExposureState?.finalized
      ? {
        defensiveInnings: match.gameExposureState.defensiveInnings,
        plateAppearances: match.gameExposureState.plateAppearances,
        role: match.role || match.playerLineupStatus || "bench"
      }
      : undefined;
    MatchExperienceDevelopment.settleMatchExperienceDevelopment(player, match, finalizedExposure ? { exposure: finalizedExposure } : {});
  }
  if (typeof HighSchoolCompetitionEvidence !== "undefined" && (match.competitionEditionId || match.competitionEntryId)) {
    HighSchoolCompetitionEvidence.integrateMatchEvidence(player, {
      playerId: match.playerId || "player",
      competitionEditionId: match.competitionEditionId,
      competitionEntryId: match.competitionEntryId,
      teamId: match.competitionTeamId,
      match,
      position: match.playerFieldingAssignment || match.position,
      role: match.role || match.playerLineupStatus,
      createdContext: { highSchoolYear: match.highSchoolYear, opportunityIndex: match.opportunityIndex }
    });
  }

  if (participationTruth.participated) {
    player.seasonPerformance += Math.max(0, contribution.strong * 2 + contribution.mixed);
    player.recentPerformance += overallTier === "strong" ? 2 : overallTier === "mixed" ? 1 : -1;
    player.exposure += overallTier === "strong" ? 2 : 1;
    player.scoutEvaluation += overallTier === "strong" ? 2 : overallTier === "mixed" ? 1 : 0;
    const proofFlag = finalDecision === "attack" ? "showcase_tools" : finalDecision === "advance" ? "showcase_baseball_iq" : "showcase_team_task";
    addFlags(["hs_y1_match_completed", `hs_y1_match_${overallTier}`, proofFlag]);
  } else {
    addFlags(["hs_y1_match_completed", "hs_y1_match_no_appearance"]);
  }
  const competitionSettlement = applyHighSchoolCompetitionMatchSettlement(match);
  if (competitionSettlement?.status === "applied") {
    const labels = HighSchoolCompetitionReassessment.ROLE_LABELS || {};
    const roleResult = competitionSettlement.roleResult || {};
    const roleText = roleResult.change === "unchanged"
      ? `正式角色維持「${labels[roleResult.nextRole] || player.highSchoolTeamRole || "待評估"}」`
      : `正式角色由「${labels[roleResult.currentRole] || roleResult.currentRole}」調整為「${labels[roleResult.nextRole] || roleResult.nextRole}」`;
    match.competitionFeedback = `${roleText}；評估趨勢：${formatHighSchoolCompetitionEvaluation(competitionSettlement.evaluation)}。`;
    match.consequence = `${match.consequence} ${match.competitionFeedback}`;
  }
  recordHighSchoolYearOneMatchHistory(match, competitionSettlement);
  if (typeof HighSchoolScheduleOpportunity !== "undefined" && player.highSchoolSchedule) {
    HighSchoolScheduleOpportunity.markScheduleCompleted(player.highSchoolSchedule,match);
    recordHighSchoolExchangeCompletion(match);
  }
  return match.performanceSummary;
}

function applyHighSchoolCompetitionMatchSettlement(match) {
  if (!match?.completed || !match?.gameExposureState?.finalized || typeof HighSchoolCompetitionReassessment === "undefined") return null;
  const identity = getHighSchoolCompetitionEvaluationIdentity(player);
  const readiness = createHighSchoolOpportunityReadinessSnapshot(
    match.gameExposureState.opportunitySnapshot?.assignedPosition || player.primaryPosition,
    player
  );
  const evidence = HighSchoolCompetitionReassessment.collectCompetitionEvidence({
    match,
    exposure: match.gameExposureState,
    readiness,
    coachTrust: player.relationships?.coachTrust,
    health: player.body
  });
  const evaluationUpdate = HighSchoolCompetitionReassessment.updateCompetitionEvaluation(
    player.highSchoolCompetitionEvaluation,
    evidence,
    identity
  );
  if (evaluationUpdate.status !== "applied") return evaluationUpdate;

  player.highSchoolCompetitionEvaluation = evaluationUpdate.state;
  const competition = refreshSelectedPositionCompetitionContext(player, readiness.position)
    || player.schoolInvitationState?.selectedPositionCompetitionContext
    || {};
  const roleResult = HighSchoolCompetitionReassessment.reassessRole({
    currentRole: player.highSchoolRoleCode,
    evaluation: player.highSchoolCompetitionEvaluation,
    competition,
    readiness,
    coachTrust: player.relationships?.coachTrust
  });
  HighSchoolCompetitionReassessment.applyRoleResult(player, roleResult);
  const refreshedRoster = materializeSelectedHighSchoolRoster(player, {
    rosterRole: roleResult.nextRole === "starter" ? "starter" : "bench",
    playerPosition: readiness.position,
    refreshCompetition: true
  });
  const refreshedCompetition = refreshedRoster
    ? player.schoolInvitationState.selectedPositionCompetitionContext
    : competition;
  player.highSchoolCompetitionEvaluation.lastReassessmentReason = roleResult.reasons.slice();
  player.highSchoolCompetitionEvaluation.lastReassessmentAt = `${match.id}|settled`;

  const currentOpportunity = match.gameExposureState.opportunitySnapshot || {};
  const opportunityIndex = Math.max(1, Number(match.opportunityIndex || currentOpportunity.opportunityIndex) || 1);
  player.highSchoolOpportunityHistory = HighSchoolCompetitionReassessment.recordOpportunity(player.highSchoolOpportunityHistory, {
    opportunity: currentOpportunity,
    opportunityIndex,
    roleAtCreation: currentOpportunity.actualRole || match.role,
    actualExposure: {
      appearanceType: match.gameExposureState.appearanceType,
      started: match.gameExposureState.appearanceType === "start",
      participated: match.gameExposureState.plateAppearances > 0 || match.gameExposureState.defensiveInnings > 0,
      plateAppearances: match.gameExposureState.plateAppearances,
      defensiveInnings: match.gameExposureState.defensiveInnings
    },
    evaluationConsequence: {
      evaluationIdentity: identity,
      accumulatedScore: player.highSchoolCompetitionEvaluation.accumulatedScore,
      trend: player.highSchoolCompetitionEvaluation.recentTrend,
      roleChange: roleResult.change,
      nextRole: roleResult.nextRole,
      reasons: roleResult.reasons.slice()
    }
  });

  const highSchoolYear = Math.max(1, Number(match.highSchoolYear) || 1);
  const nextOpportunity = highSchoolYear === 1 && opportunityIndex === 1 ? createHighSchoolPlayingTimeOpportunity({
    matchId: "hs-y1-followup-evaluation-2",
    actualRole: player.highSchoolRoleCode,
    requestedPosition: readiness.position,
    directStartForced: false,
    opportunityIndex: 2,
    opportunityPhase: "post-autumn-evaluation",
    evaluationTrend: player.highSchoolCompetitionEvaluation.trendScore,
    previousActualExposure: match.gameExposureState
  }) : null;
  player.highSchoolNextOpportunity = nextOpportunity ? cloneSchoolInvitationValue({
    ...nextOpportunity,
    opportunityIndex: 2,
    phase: "post-autumn-evaluation",
    evaluationIdentity: identity,
    previousMatchId: match.id,
    competitionSnapshot: refreshedCompetition
  }) : null;
  if (nextOpportunity) {
    player.highSchoolOpportunityHistory = HighSchoolCompetitionReassessment.recordOpportunity(player.highSchoolOpportunityHistory, {
      opportunity: nextOpportunity,
      opportunityIndex: 2,
      roleAtCreation: player.highSchoolRoleCode
    });
    player.highSchoolRoleContext.opportunity = getHighSchoolPlayingTimeAssignmentText(nextOpportunity);
  }
  return { status: "applied", evidence, evaluation: player.highSchoolCompetitionEvaluation, roleResult, competition: refreshedCompetition, nextOpportunity: player.highSchoolNextOpportunity };
}

function finalizeHighSchoolGameRecord(match) {
  if (!match || typeof MatchGameRecord === "undefined") return null;
  if (!match.gameRecord) {
    match.gameRecord = MatchGameRecord.createGameRecord({
      gameId: match.id,
      competitionEditionId: match.competitionEditionId,
      competitionEntryId: match.competitionEntryId,
      homeTeamId: match.matchContext?.homeTeamId || match.competitionTeamId || match.rosters?.home?.teamRoster?.teamId || "home",
      awayTeamId: match.matchContext?.awayTeamId || match.rosters?.away?.teamRoster?.teamId || "away",
      inningsScheduled: match.regulationInnings,
      rosters: match.rosters
    });
  }
  return MatchGameRecord.finalizeGameRecord(match.gameRecord, {
    inningsPlayed: match.inning,
    competitionEditionId: match.competitionEditionId,
    competitionEntryId: match.competitionEntryId
  });
}

function validateActiveDefense(roster) {
  const issues = [];
  const lineup = Array.isArray(roster?.lineup) ? roster.lineup : [];
  const bench = Array.isArray(roster?.bench) ? roster.bench : [];
  if (roster?.bench && !Array.isArray(roster.bench)) issues.push("active-bench-invalid");
  const benchIds = new Set(bench.flatMap(actor => [actor?.id, actor?.playerId].filter(Boolean)));
  const rosterPlayers = Array.isArray(roster?.teamRoster?.players) ? roster.teamRoster.players : null;
  if ((roster?.teamRoster || roster?.source === VERSION) && !rosterPlayers) issues.push("active-roster-reference-missing");
  const actorIds = new Set();
  const playerIds = new Set();
  const positions = new Set();
  if (lineup.length !== POSITION_ORDER.length) issues.push("active-defense-size");
  for (const actor of lineup) {
    const id = actor?.id;
    const playerId = actor?.playerId || id;
    const code = normalizePosition(actor?.defensivePosition || actor?.position);
    if (!id || actorIds.has(id) || playerIds.has(playerId)) issues.push("active-actor-identity");
    if (benchIds.has(id) || benchIds.has(playerId)) issues.push("active-actor-on-bench");
    actorIds.add(id);
    playerIds.add(playerId);
    if (!code || positions.has(code)) issues.push("active-position-duplicate-or-invalid");
    positions.add(code);
    if (actor?.position && normalizePosition(actor.position) !== code) issues.push("active-position-alias-conflict");
    if (!isHighSchoolPositionAssignmentLegal(actor, code)) issues.push("active-position-ineligible");
    if (rosterPlayers && !rosterPlayers.some(item => item.id === id && (!actor.playerId || item.playerId === actor.playerId))) {
      issues.push("active-actor-not-in-roster");
    }
  }
  for (const code of POSITION_ORDER) if (!positions.has(code)) issues.push(`active-position-missing-${code}`);
  return { ok: issues.length === 0, issues };
}

function validateRoster(roster) {
  const errors = [];
  if (roster?.version !== VERSION) errors.push("version-invalid");
  if (!Array.isArray(roster?.starters) || roster.starters.length !== 9) errors.push("starter-count-invalid");
  const assignments = (roster?.battingOrder || []).map(slot => slot.defensivePosition);
  if (assignments.length !== 9 || new Set(assignments).size !== 9 || POSITION_ORDER.some(position => !assignments.includes(position))) errors.push("position-coverage-invalid");
  const playerIds = (roster?.battingOrder || []).map(slot => slot.playerId);
  if (new Set(playerIds).size !== playerIds.length) errors.push("batting-order-duplicate");
  const byId = new Map((roster?.players || []).map(player => [player.playerId, player]));
  (roster?.battingOrder || []).forEach(slot => {
    const actor = byId.get(slot.playerId);
    if (!actor || !isPositionEligible(actor, slot.defensivePosition)) errors.push(`illegal-assignment:${slot.playerId}:${slot.defensivePosition}`);
  });
  if (!roster?.pitchingStaff?.starter || !(roster?.pitchingStaff?.secondaryPitchers || []).length) errors.push("pitching-staff-incomplete");
  return Object.freeze({ ok: errors.length === 0, errors: Object.freeze(errors) });
}

function getEventId(record, event = {}) {
  if (event.eventId) return String(event.eventId);
  return [record.gameId, Math.max(1, integer(event.inning) || 1), String(event.half || ""), integer(event.sequence)].join("|");
}

function recordEvent(record, event = {}, context = {}) {
  check(record?.version === VERSION, "Game record schema is required");
  if (FINAL_STATUSES.has(record.status)) return Object.freeze({ status: "locked", eventId: getEventId(record, event) });
  const eventId = getEventId(record, event);
  if (record.eventRefs.some(ref => ref.eventId === eventId)) return Object.freeze({ status: "duplicate", eventId });
  validateDefensiveAttribution(event);
  ensureInningLine(record, event.inning || 1);
  if (event.type === "plateAppearance") recordPlateAppearance(record, event, context, eventId);
  if (event.type === "run") recordRun(record, event, context);
  if (event.type === "playerRoutinePlay" || (event.type === "meaningfulMomentResolved" && event.domain === "defense") || event.type === "defensivePlay") {
    recordDefensivePlay(record, event, context, eventId);
  }
  if (event.type === "playerEntry" || event.type === "positionChange") {
    const side = event.team || context.playerTeam || "home";
    const line = ensurePlayerLine(record, event.playerId || context.playerId || "player", {
      teamId: side === "away" ? record.awayTeamId : record.homeTeamId,
      role: event.role || context.playerRole || "substitute",
      position: event.playerPosition || context.playerPosition
    });
    if (line) {
      line.role = String(event.role || context.playerRole || "substitute");
      addPositionAppearance(line, event.playerPosition || context.playerPosition, line.role, eventId);
    }
  }
  recordRunnerEvent(record, event, context);
  const pitcherOuts = attributePitcherOuts(record, event, context);
  record.eventRefs.push({ eventId, type: String(event.type || "event"), sequence: integer(event.sequence), inning: Math.max(1, integer(event.inning) || 1), half: String(event.half || ""),
    ...(event.defensiveAttribution ? { defensivePlayIdentity: event.defensiveAttribution.playIdentity } : {}), ...(pitcherOuts ? { pitcherOuts } : {}) });
  return Object.freeze({ status: "applied", eventId });
}

function finalizeGameRecord(record, input = {}) {
  check(record?.version === VERSION, "Game record schema is required");
  if (FINAL_STATUSES.has(record.status)) return Object.freeze({ status: "duplicate", record: clone(record) });
  if (input.competitionEditionId) record.competitionEditionId = String(input.competitionEditionId);
  if (input.competitionEntryId) record.competitionEntryId = String(input.competitionEntryId);
  record.inningsPlayed = Math.max(record.inningsPlayed, integer(input.inningsPlayed));
  for (let inning = 1; inning <= record.inningsPlayed; inning += 1) ensureInningLine(record, inning);
  const awayRuns = integer(record.totals.away.runs);
  const homeRuns = integer(record.totals.home.runs);
  record.result = {
    winnerTeamId: homeRuns === awayRuns ? null : homeRuns > awayRuns ? record.homeTeamId : record.awayTeamId,
    loserTeamId: homeRuns === awayRuns ? null : homeRuns > awayRuns ? record.awayTeamId : record.homeTeamId,
    finalScore: { away: awayRuns, home: homeRuns },
    tie: homeRuns === awayRuns
  };
  const issues = getIntegrityIssues(record);
  record.integrity = { checked: true, issues };
  check(issues.length === 0, `Game record integrity failed: ${issues.join(",")}`);
  record.status = "final";
  record.finalizedAtEventId = record.eventRefs.at(-1)?.eventId || null;
  return Object.freeze({ status: "finalized", record: clone(record) });
}

function normalizeGameRecord(saved, config = {}) {
  if (!saved) return createGameRecord(config);
  check(saved.version === VERSION, "Unsupported game record schema");
  const record = createGameRecord({
    ...config,
    gameId: saved.gameId,
    competitionEditionId: saved.competitionEditionId,
    competitionEntryId: saved.competitionEntryId,
    homeTeamId: saved.homeTeamId,
    awayTeamId: saved.awayTeamId,
    inningsScheduled: saved.inningsScheduled
  });
  record.status = FINAL_STATUSES.has(saved.status) ? "final" : "active";
  record.inningsPlayed = integer(saved.inningsPlayed);
  record.inningLines = (saved.inningLines || []).map(line => ({ inning: Math.max(1, integer(line.inning) || 1), awayRuns: integer(line.awayRuns), homeRuns: integer(line.homeRuns) }));
  record.totals = {
    away: { runs: integer(saved.totals?.away?.runs), hits: integer(saved.totals?.away?.hits), errors: integer(saved.totals?.away?.errors) },
    home: { runs: integer(saved.totals?.home?.runs), hits: integer(saved.totals?.home?.hits), errors: integer(saved.totals?.home?.errors) }
  };
  record.result = saved.result ? clone(saved.result) : null;
  record.playerLines = Object.fromEntries(Object.entries(saved.playerLines || {}).map(([id, line]) => [id, normalizePlayerLine(line, { playerId: id })]));
  record.eventRefs = (saved.eventRefs || []).map(ref => ({ eventId: String(ref.eventId), type: String(ref.type || "event"), sequence: integer(ref.sequence), inning: Math.max(1, integer(ref.inning) || 1), half: String(ref.half || ""),
    ...(ref.defensivePlayIdentity ? { defensivePlayIdentity: String(ref.defensivePlayIdentity) } : {}),
    ...(ref.pitcherOuts ? { pitcherOuts: { pitcherId: String(ref.pitcherOuts.pitcherId), outs: integer(ref.pitcherOuts.outs) } } : {}) }));
  record.integrity = { checked: saved.integrity?.checked === true, issues: Array.isArray(saved.integrity?.issues) ? saved.integrity.issues.map(String) : [] };
  record.finalizedAtEventId = saved.finalizedAtEventId ? String(saved.finalizedAtEventId) : null;
  const issues = getIntegrityIssues(record);
  check(issues.length === 0, `Restored game record integrity failed: ${issues.join(",")}`);
  return record;
}

function createPlateAppearanceIdentity(input = {}) {
  return [input.matchId || "match", input.paId || input.momentId || "pa", input.batterId || "player", input.inning || 0, input.half || ""].join("|");
}

function recordHighSchoolMatchSimulationEvent(match, event) {
  if (event.type === "plateAppearance" && /Pending$/.test(event.result || "")) throw new Error("Pending defense cannot enter the official PA ledger");
  if (!Array.isArray(match.simulationLog)) match.simulationLog = [];
  const defaultImportance = getHighSchoolMatchEventPresentationImportance(event);
  const record = Object.assign({ sequence: match.simulationLog.length, presentationImportance: defaultImportance }, event);
  if (record.scores) record.scores = { ...record.scores };
  if (record.runners) record.runners = record.runners.slice(0, 3);
  if (Array.isArray(record.runnerChanges)) record.runnerChanges = record.runnerChanges.map(change => ({ ...change }));
  if (Array.isArray(record.scoringRunnerIds)) record.scoringRunnerIds = record.scoringRunnerIds.slice();
  record.presentationSnapshot = createHighSchoolMatchPresentationSnapshot(match, record);
  match.simulationLog.push(record);
  if (typeof MatchGameRecord !== "undefined") {
    if (!match.gameRecord) {
      match.gameRecord = MatchGameRecord.createGameRecord({
        gameId: match.id,
        competitionEditionId: match.competitionEditionId,
        competitionEntryId: match.competitionEntryId,
        homeTeamId: match.matchContext?.homeTeamId || match.competitionTeamId || match.rosters?.home?.teamRoster?.teamId || "home",
        awayTeamId: match.matchContext?.awayTeamId || match.rosters?.away?.teamRoster?.teamId || "away",
        inningsScheduled: match.regulationInnings,
        rosters: match.rosters
      });
    }
    MatchGameRecord.recordEvent(match.gameRecord, record, {
      rosters: match.rosters,
      playerId: "player",
      playerTeam: getHighSchoolPlayerTeamSide(match),
      playerRole: match.playerLineupStatus || match.role,
      playerPosition: match.playerFieldingAssignment || match.currentFieldingPosition || match.position
    });
  }
  return record;
}

function deriveHighSchoolMatchActualExposure(match) {
  const log = Array.isArray(match?.simulationLog) ? match.simulationLog : [];
  const entryEvent = log.find(event => event.type === "playerEntry") || null;
  const started = match?.playerLineupStatus === "starter";
  const participated = started || (match?.playerLineupStatus === "substitute" && (match.playerEntryCompleted || entryEvent));
  if (!participated) {
    return Object.freeze({ matchId: match?.id || "", participated: false, started: false, appearanceType: "noAppearance", entryInning: null, exitInning: null, defensiveInnings: 0, plateAppearances: 0, role: match?.role || "bench" });
  }
  const entrySequence = started ? -1 : Number(entryEvent?.sequence) || 0;
  const defensiveInnings = new Set(log.filter(event => event.type === "halfInningEnd" && event.half === (getHighSchoolPlayerTeamSide(match) === "home" ? "上" : "下")
    && Number(event.sequence) >= entrySequence).map(event => Number(event.inning) || 0).filter(Boolean)).size;
  const plateAppearances = log.filter(event => event.type === "plateAppearance" && event.batterId === "player"
    && Number(event.sequence) >= entrySequence).length;
  return Object.freeze({
    matchId: match?.id || "",
    participated: true,
    started,
    appearanceType: started ? "start" : match?.gameExposureState?.plannedUsage?.appearanceType || "lateGameAppearance",
    entryInning: started ? 1 : Number(entryEvent?.inning) || Number(match?.inning) || 1,
    exitInning: Number(match?.inning) || null,
    defensiveInnings,
    plateAppearances,
    role: match?.role || match?.playerLineupStatus || "bench"
  });
}

function getHighSchoolOffensivePlayerPANumber(match) {
  return (match?.simulationLog || []).filter(event => event.type === "plateAppearance" && event.batterId === "player").length + 1;
}

function evaluateHighSchoolOffensivePlayerAgency(match, classification = null) {
  const regulationInnings = Math.max(1, Math.floor(Number(match?.regulationInnings) || 7));
  const inning = Math.max(1, Math.floor(Number(match?.inning) || 1));
  const batter = getHighSchoolMatchLineupBatter(match, match?.offenseTeam);
  const playerActive = isHighSchoolMatchPlayerActive(match);
  const playerBatting = match?.offenseTeam === getHighSchoolPlayerTeamSide(match) && batter?.id === "player";
  const gameLive = !match?.completed && !match?.pendingGameSettlement && Number(match?.outs) < 3 && !isHighSchoolMatchWalkOff(match);
  const playerPANumber = classification?.playerPANumber || getHighSchoolOffensivePlayerPANumber(match);
  const candidateIdentity = [match?.id || "match", "agency", inning, match?.half || "", playerPANumber, "player"].join("|");
  const priorAgency = match?.offensivePlayerAgencyState;
  const alreadyResolved = priorAgency?.agencyIdentity === candidateIdentity && (priorAgency.resultApplied === true || priorAgency.status === "resolved");
  const lateGamePlayerAgency = Boolean(gameLive && playerActive && playerBatting && inning >= regulationInnings && !alreadyResolved);
  return Object.freeze({
    version: "offensive-player-agency-v1",
    agencyReason: lateGamePlayerAgency ? "late-game-canonical-player-pa" : alreadyResolved ? "canonical-pa-already-resolved" : "agency-not-required",
    lateGamePlayerAgency,
    gameLive,
    playerActive,
    playerBatting,
    inning,
    half: match?.half || "",
    regulationInnings,
    playerPANumber,
    leverageClass: classification?.leverageClass || "routine"
  });
}

function applyHighSchoolRoleState(code, options = {}) {
  const labels = typeof HighSchoolCompetitionReassessment !== "undefined"
    ? HighSchoolCompetitionReassessment.ROLE_LABELS
    : { starter: "先發／關鍵任務", rotation: "輪替／替補任務", bench: "發展／板凳任務" };
  const normalized = ["starter", "rotation", "bench"].includes(code) ? code : "bench";
  player.highSchoolRoleCode = normalized;
  player.highSchoolTeamRole = labels[normalized];
  player.highSchoolRoleContext = {
    ...(player.highSchoolRoleContext || {}),
    code: normalized,
    label: labels[normalized],
    evidence: Array.isArray(options.evidence) ? options.evidence.slice() : player.highSchoolRoleContext?.evidence || [],
    opportunity: options.opportunity === undefined ? player.highSchoolRoleContext?.opportunity || "" : options.opportunity,
    assignment: options.assignment === undefined ? player.highSchoolRoleContext?.assignment || "" : options.assignment
  };
  return player.highSchoolRoleContext;
}

function restoreHighSchoolMatchAfterDefensiveDecision(match, fallbackPhase = "moment_2_resolved") {
  const activeSituation = typeof MatchSituationLifecycle !== "undefined"
    ? MatchSituationLifecycle.normalizeSituation(match?.activeSituation) : null;
  if (activeSituation && !MatchSituationLifecycle.canResumeSimulation(activeSituation)) return match.simulationPhase;
  const resume = match?.pendingDefensiveResumeState;
  if (resume) {
    match.simulationPhase = resume.simulationPhase || fallbackPhase;
    match.momentIndex = Math.max(0, Math.min(2, Number(resume.momentIndex) || 0));
    match.currentMomentId = resume.currentMomentId || match.currentMomentId;
    match.currentDomain = resume.currentDomain || "flow";
  } else {
    match.simulationPhase = fallbackPhase;
  }
  match.pendingDefensiveResumeState = null;
  return match.simulationPhase;
}

function classifyHighSchoolMatchDefensiveOpportunity(match, situation, legalChoices = [], playerInvolved = true) {
  const classification = classifyPositionFamilyPlay(situation, legalChoices, playerInvolved);
  const density = evaluateHighSchoolMatchDefensiveDecisionDensity(match, situation, legalChoices, classification);
  if (classification.eventClassification !== "playerMeaningfulDecision" || density.allowed) {
    return Object.freeze({ ...classification, density });
  }
  return Object.freeze({
    eventClassification: "playerRoutinePlay",
    decisionTension: "low",
    gate: classification.gate,
    density
  });
}

function getHighSchoolPhysicalDefensePlayerContext(match, physicalTruth, defenderContext, options = {}) {
  const opportunity = getHighSchoolDefensiveOpportunity(match, physicalTruth);
  if (!opportunity) return defenderContext; // Pre-foundation isolated harness compatibility.
  if (opportunity.bindingStatus === "invalid") throw new Error("Active defense integrity failed: defensive opportunity binding");
  const ownsGroundSlice = opportunity.supported && opportunity.primaryDefenderId === "player"
    && (opportunity.primaryPosition === "2B" || (["SS", "3B", "1B"].includes(opportunity.primaryPosition) && physicalTruth.ballType === "groundBall"));
  const firstBase = TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], "1B");
  const continuation = options.incomingContinuation;
  const liveContinuation = continuation?.version === "incoming-continuation-admission-v1"
    && continuation.matchId === match.id && continuation.batterId === match.currentBatter
    && continuation.inning === match.inning && continuation.half === match.half
    && continuation.offenseTeam === match.offenseTeam && continuation.defenseTeam === match.defenseTeam
    && continuation.outs === match.outs && JSON.stringify(continuation.runners) === JSON.stringify(match.runners);
  const receivesGroundSlice = firstBase?.id === "player" && physicalTruth.ballType === "groundBall"
    && liveContinuation && opportunity.supported && ["SS", "2B", "3B"].includes(opportunity.primaryPosition);
  const npc = receivesGroundSlice ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], opportunity.primaryPosition) : null;
  const acquisition = npc ? getDefensiveSimulationCapability(npc, npc.position, match) : defenderContext;
  return { ...defenderContext, ...acquisition, playerPosition: ownsGroundSlice || receivesGroundSlice ? TeamRosterFoundation.POSITION_LABELS[opportunity.primaryPosition] : "",
    defensiveOpportunity: opportunity,
    ...(ownsGroundSlice || receivesGroundSlice ? { reachAccess: getHighSchoolReachAccess(match, physicalTruth, opportunity, acquisition) } : {}) };
}

function getHighSchoolInfieldAssignmentPosition(match, playerContext = player) {
  if (infieldPositions.includes(match?.currentFieldingPosition)) return match.currentFieldingPosition;
  if (infieldPositions.includes(match?.position)) return match.position;
  if (infieldPositions.includes(playerContext?.primaryPosition)) return playerContext.primaryPosition;
  const secondary = (playerContext?.secondaryPositions || []).find(position => infieldPositions.includes(position));
  if (secondary && match?.position === secondary) return secondary;
  return { starter: "游擊手", rotation: "二壘手", bench: "三壘手" }[match?.role] || "游擊手";
}

function createHighSchoolOffensivePlateAppearanceIdentity(match, choice) {
  return OffensivePlateApproach.createPlateAppearanceIdentity({
    matchId: match?.id,
    paId: choice?.matchMomentId || getHighSchoolYearOneMomentId(match),
    batterId: "player",
    inning: match?.inning,
    half: match?.half
  });
}

function createGroundBallMatchSituation(match, legalChoices, classification, opportunity = null) {
  validateHighSchoolReceiverSourceMetadata(match);
  if (!match || typeof MatchSituationLifecycle === "undefined" || !match.groundBallInPlayState?.supported
    || match.defensiveSituation?.familyId !== "infield") return null;
  const handoff = match.groundBallInPlayState;
  assertHighSchoolGroundParticipant(match);
  const situationId = MatchSituationLifecycle.createSituationId({
    gameId: match.id,
    inning: match.inning,
    half: match.half,
    paIdentity: handoff.identity,
    simulationPoint: opportunity?.opportunityId || match.currentMomentId || match.simulationCursor,
    type: MatchSituationLifecycle.TYPES.groundBallDefensiveDecision
  });
  const existing = MatchSituationLifecycle.normalizeSituation(match.activeSituation);
  if (existing?.situationId === situationId) {
    match.activeSituation = existing;
    return existing;
  }
  if (existing && !MatchSituationLifecycle.canResumeSimulation(existing)) return existing;
  const presentationText = getHighSchoolDefensiveSituationText(match);
  let situation = MatchSituationLifecycle.createSituation({
    situationId,
    type: MatchSituationLifecycle.TYPES.groundBallDefensiveDecision,
    actor: {
      id: "player",
      role: match.defensiveSituation.responsibility?.playerRole || "",
      position: match.defensiveSituation.playerPosition || ""
    },
    sourceAuthority: "BattedBallPhysicalTruth+GroundBallRunnerRealization+InfieldRouteAvailability",
    sourcePhysicalStateRef: handoff.identity,
    createdAt: {
      inning: match.inning,
      half: match.half,
      outs: match.outs,
      score: { ...match.scores },
      bases: match.runners.slice(0, 3),
      paIdentity: handoff.identity,
      simulationPoint: opportunity?.opportunityId || match.currentMomentId || match.simulationCursor
    },
    contextSnapshot: {
      familyId: "infield",
      playerPosition: match.defensiveSituation.playerPosition,
      ...(handoff.firstBaseContext ? { firstBaseContext: handoff.firstBaseContext } : {}),
      ballContext: handoff.ballContext,
      physicalIdentity: handoff.physicalTruth?.identity || "",
      ...(handoff.receiverSourcePin ? { receiverSourcePin: handoff.receiverSourcePin } : {}),
      runnerRealization: handoff.runnerRealization,
      forceState: handoff.forceState,
      timingWindows: handoff.timingWindows,
      presentationText
    },
    legalRoutes: legalChoices,
    recommendation: {
      direction: match.coachTacticalDirection ? JSON.parse(JSON.stringify(match.coachTacticalDirection)) : null,
      presentation: match.coachInstruction || ""
    },
    previousSituationSummary: match.lastClosedSituationSummary || null
  });
  situation = MatchSituationLifecycle.admitSituation(situation, {
    supported: true,
    playerOwnsDecision: classification?.eventClassification === "playerMeaningfulDecision",
    reason: classification?.eventClassification === "playerMeaningfulDecision"
      ? "groundBallMultipleMeaningfulRoutes" : "groundBallAutomaticResolution"
  });
  if (situation.admission.admittedToPlayer) situation = MatchSituationLifecycle.presentSituation(situation);
  match.activeSituation = situation;
  return situation;
}

function getHighSchoolYearOneMatchMomentChoices(match = prepareCurrentHighSchoolYearOneMatch()) {
  const activeSituation = typeof MatchSituationLifecycle !== "undefined"
    ? MatchSituationLifecycle.normalizeSituation(match?.activeSituation) : null;
  if (activeSituation?.type === "plateDecision"
    && activeSituation.lifecycleState === "presented") return getHighSchoolPlateDecisionChoices(match);
  if (match?.simulationPhase === "offensive_agency_ready") return getHighSchoolOffensiveAgencyChoices(match);
  const momentId = getHighSchoolYearOneMomentId(match);
  if (!momentId) return [];
  if (match.momentIndex === 1) {
    return getHighSchoolDefensiveMomentChoices(match);
  }
  ensureHighSchoolBatterAnticipationState(match);
  return buildOffensiveDecisionChoices(match).filter(choice => isOffensiveDecisionChoiceLegal(choice, match));
}

function isOffensiveDecisionChoiceLegal(choice, match) {
  if (!choice || choice.executionOnly || match?.currentDomain === "defense") return false;
  const context = analyzeHighSchoolOffensiveDecisionContext(match);
  const runnerObjectives = new Set(["advanceRunner", "scoreRunner", "avoidDoublePlay"]);
  if (!context.hasRunner && runnerObjectives.has(choice.objective)) return false;
  if (context.twoOuts && ["sacrificeAdvance", "sacrificeFly"].includes(choice.objective)) return false;
  if (context.twoOuts && ["sacrificeAdvance", "sacrificeFly"].includes(choice.route)) return false;
  const checks = {
    runnerOnFirst: context.first,
    runnerOnSecond: context.second,
    runnerOnThird: context.third,
    runnerInScoringPosition: context.scoringPosition,
    anyRunner: context.hasRunner,
    fewerThanTwoOuts: !context.twoOuts,
    doublePlayPossible: context.first && !context.twoOuts
  };
  return (choice.requirements || []).every(requirement => checks[requirement] === true);
}

function resolveDefensiveOpportunity({ physicalTruth, activeRoster, topologyVersion = TOPOLOGY_VERSION } = {}) {
  const opportunity = deriveDefensiveOpportunity(physicalTruth, topologyVersion);
  if (!opportunity.supported) return opportunity;
  const assignment = Roster.validateActiveDefense(activeRoster);
  if (!assignment.ok) return freeze({ ...opportunity, supported: false, bindingStatus: "invalid",
    fallbackReason: "invalidActiveAssignment", assignmentIssues: assignment.issues.slice() });
  const primary = Roster.getCurrentDefender(activeRoster, opportunity.primaryPosition);
  const secondaryDefenders = opportunity.secondaryPositions.map(position => ({
    position, defenderId: Roster.getCurrentDefender(activeRoster, position)?.id || ""
  }));
  if (!primary || secondaryDefenders.some(actor => !actor.defenderId)) {
    return freeze({ ...opportunity, supported: false, bindingStatus: "invalid", fallbackReason: "activeDefenderUnavailable" });
  }
  return freeze({ ...opportunity, primaryDefenderId: primary.id, secondaryDefenders, bindingStatus: "bound" });
}

function admitSituation(situation, input = {}) {
  const routes = normalizeRoutes(situation.legalRoutes);
  const meaningfulRouteIds = [...new Set(routes.map(route => route.routeId || route.id || route.matchDecision).filter(Boolean))];
  const supported = input.supported !== false;
  const playerOwnsDecision = input.playerOwnsDecision === true;
  const admittedToPlayer = supported && playerOwnsDecision && meaningfulRouteIds.length >= 2;
  const mode = !supported ? "unsupportedFallback" : admittedToPlayer ? "playerDecision"
    : meaningfulRouteIds.length <= 1 ? "automaticResolution" : "aiDecision";
  const reason = input.reason || (admittedToPlayer ? "multipleBehaviorallyDistinctPlayerRoutes"
    : !supported ? "unsupportedSituation"
      : meaningfulRouteIds.length <= 1 ? "fewerThanTwoMeaningfulRoutes" : "playerDecisionOwnershipDenied");
  return transition(situation, "admitted", {
    admission: { mode, admittedToPlayer, reason, meaningfulRouteCount: meaningfulRouteIds.length }
  }, { reason });
}

function collectCompetitionEvidence(input = {}) {
  const match = input.match || {};
  const exposure = input.exposure || match.gameExposureState || {};
  const readiness = input.readiness || exposure.opportunitySnapshot?.readinessSnapshot || {};
  const contribution = match.playerContribution || {};
  const moments = Array.isArray(match.completedMoments) ? match.completedMoments : [];
  const matchExperience = match.matchExperience || {};
  const matchExperienceSummary = matchExperience.evidenceSummary || {};
  const started = exposure.started === true || exposure.appearanceType === "start";
  const plateAppearances = Math.max(0, Number(exposure.plateAppearances) || 0);
  const defensiveInnings = Math.max(0, Number(exposure.defensiveInnings) || 0);
  const enteredGame = exposure.participated === true || started || plateAppearances > 0 || defensiveInnings > 0;
  const strong = Math.max(0, Number(contribution.strong) || 0);
  const mixed = Math.max(0, Number(contribution.mixed) || 0);
  const failure = Math.max(0, Number(contribution.failure) || 0);
  const errors = Math.max(0, Number(contribution.errors) || 0);
  const performanceSamples = Math.max(strong + mixed + failure, moments.length, Math.min(plateAppearances + Math.min(defensiveInnings, 2), 4));
  const contributionQuality = performanceSamples > 0
    ? ((strong * 2.4) + (mixed * 0.45) - (failure * 2.2) - (errors * 0.8)) / performanceSamples : 0;
  const momentQuality = moments.length
    ? moments.reduce((sum, moment) => sum + getMomentQuality(moment), 0) / moments.length : 0;
  const quality = enteredGame ? clamp((contributionQuality * 1.6) + (momentQuality * 0.55), -5, 5) : 0;
  const sampleConfidence = enteredGame ? clamp(performanceSamples / 3, 0.25, 1) : 0;
  const positionReadiness = clamp(readiness.positionReadiness, 0, 10, 5);
  const positionFit = clamp(readiness.positionFit, 0, 10, 5);
  const coachTrust = clamp(input.coachTrust, 0, 20, 0);
  const health = input.health || {};
  const fatigue = clamp(health.fatigue, 0, 20, 0);
  const injuryRisk = clamp(health.injuryRisk, 0, 20, 0);
  const pain = clamp(health.pain, 0, 20, 0);
  const trainingScore = clamp(
    ((positionReadiness - 5) * 0.7) + ((positionFit - 5) * 0.3) + ((coachTrust - 6) * 0.12)
      - (fatigue * 0.04) - (injuryRisk * 0.08) - (pain * 0.12),
    -3,
    3
  );
  const sampleScore = round((quality * sampleConfidence) + (trainingScore * 0.35));
  return Object.freeze({
    matchIdentity: String(match.id || input.matchIdentity || ""),
    trainingEvidence: Object.freeze({ positionReadiness, positionFit, coachTrust, fatigue, injuryRisk, pain, score: round(trainingScore) }),
    exposureEvidence: Object.freeze({ started, enteredGame, noAppearance: !enteredGame, appearanceType: exposure.appearanceType || (enteredGame ? "appearance" : "noAppearance"), plateAppearances, defensiveInnings }),
    matchEvidence: Object.freeze({
      quality: round(quality), sampleSize: performanceSamples, sampleConfidence: round(sampleConfidence),
      strong, mixed, failure, errors, decisionExecutionSamples: moments.length,
      matchExperienceEvidenceCount: Math.max(0, Number(matchExperienceSummary.total) || 0),
      activeExperienceEvidenceCount: Math.max(0, Number(matchExperienceSummary.active) || 0),
      developmentContextCount: Array.isArray(matchExperience.selectedContexts) ? matchExperience.selectedContexts.length : 0,
      matchExperienceSettlementId: String(matchExperience.matchExperienceSettlementId || "")
    }),
    sampleScore
  });
}

function updateCompetitionEvaluation(saved, evidence, identity = "") {
  const state = normalizeEvaluationState(saved, identity);
  if (!evidence?.matchIdentity) return { status: "invalid", state };
  if (state.appliedMatchIdentities.includes(evidence.matchIdentity)) return { status: "duplicate", state };
  state.evidenceHistory.push(clone(evidence));
  state.evidenceHistory = state.evidenceHistory.slice(-MAX_EVIDENCE_HISTORY);
  state.appliedMatchIdentities.push(evidence.matchIdentity);
  state.appliedMatchIdentities = state.appliedMatchIdentities.slice(-12);
  state.sampleCount = state.evidenceHistory.length;
  state.trainingEvidence = clone(evidence.trainingEvidence);
  state.matchEvidence = clone(evidence.matchEvidence);
  state.exposureEvidence = clone(evidence.exposureEvidence);
  const weighted = state.evidenceHistory.map((item, index, all) => ({ value: Number(item.sampleScore) || 0, weight: index + 1 + Math.max(0, 3 - all.length) }));
  const totalWeight = weighted.reduce((sum, item) => sum + item.weight, 0) || 1;
  state.accumulatedScore = round(weighted.reduce((sum, item) => sum + item.value * item.weight, 0) / totalWeight);
  const recent = state.evidenceHistory.slice(-2);
  state.trendScore = round(recent.reduce((sum, item) => sum + (Number(item.sampleScore) || 0), 0) / Math.max(1, recent.length));
  state.recentTrend = state.trendScore >= 1 ? "positive" : state.trendScore <= -1 ? "negative" : "neutral";
  state.promotionPressure = round(clamp(state.accumulatedScore, 0, 5));
  state.demotionPressure = round(clamp(-state.accumulatedScore, 0, 5));
  state.rolePressure = state.promotionPressure >= 1.4 ? "promotion" : state.demotionPressure >= 1.4 ? "demotion" : "stable";
  return { status: "applied", state };
}

function settleMatchExperienceDevelopment(target, match, options = {}) {
  if (!enabled || options.enabled === false) return deepFreeze({ ok: true, status: "disabled", settled: false, contexts: [] });
  if (!target || !match || match.completed !== true) return deepFreeze({ ok: false, status: "rejected", errors: ["completed-match-required"] });
  const existing = normalizeMatchExperienceState(match.matchExperience, match);
  if (existing?.settled) return deepFreeze({ ok: true, status: "duplicate", duplicate: true, settled: true, state: clone(existing) });
  const state = existing || createMatchExperienceState(match);
  const exposure = options.exposure || derivePlayerExposure(match);
  const evidence = deriveMatchExperienceEvidence(match, { ...options, exposure });
  const aggregated = aggregateMatchExperience(evidence);
  const contexts = selectDevelopmentContexts(aggregated, match, "player");
  const applications = [];
  const errors = [];
  contexts.forEach(context => {
    const application = typeof applyDevelopmentResult === "function"
      ? applyDevelopmentResult(target, { ...context, metadata: { ...context.metadata, settlementId: context.settlementId } })
      : { ok: false, status: "rejected", errors: ["development-processor-unavailable"] };
    if (!application.ok) errors.push(...(application.errors || [application.status || "development-application-failed"]));
    applications.push(application);
  });
  state.finalized = true;
  state.settled = errors.length === 0;
  state.matchExperienceSettlementId = `${match.id || "match"}|${Math.max(0, Number(match.simulationSeed) || 0)}|player|${VERSION}`;
  state.exposure = {
    defensiveInnings: exposure.defensiveInnings,
    plateAppearances: exposure.plateAppearances,
    defensiveExposureValue: getDefensiveInningsExposureValue(exposure.defensiveInnings),
    plateAppearanceExposureValue: getPlateAppearanceExposureValue(exposure.plateAppearances)
  };
  state.evidence = evidence.slice(-MAX_EVIDENCE_RECORDS).map(clone);
  state.evidenceSummary = {
    total: evidence.length,
    exposure: evidence.filter(item => item.evidenceType === "exposure").length,
    active: evidence.filter(item => item.evidenceType === "active").length,
    noveltyGroups: new Set(evidence.map(item => item.novelty.semanticKey)).size
  };
  state.aggregated = aggregated.map(clone);
  state.selectedContexts = contexts.map(clone);
  state.developmentSettlementIds = contexts.map(context => context.settlementId);
  state.developmentResults = applications.map(application => clone(application.result || { status: application.status }));
  state.errors = errors.slice(0, 10);
  match.matchExperience = state;
  return deepFreeze({ ok: errors.length === 0, status: errors.length ? "rejected" : "applied", duplicate: false, settled: state.settled, contexts: clone(contexts), applications: clone(applications), state: clone(state) });
}

function completeHighSchoolEntry(options = {}) {
  const state = player?.schoolInvitationState;
  const invitationValidation = validateSchoolInvitationSet(state);
  if (!invitationValidation.ok) {
    showNotice("高中邀請資料不完整，暫時不能進入高中主篇。", "error");
    return false;
  }
  const directStartBypass = state.compatibilityMode === "direct-start-bypass";
  if (!directStartBypass && state.selectionFinalized !== true) {
    showNotice("請先確認一間高中，再進入高中主篇。", "warning");
    return false;
  }
  if (!directStartBypass && !state.selectedSchoolRoster) {
    materializeSelectedHighSchoolRoster(player, { rosterRole: "bench" });
  }
  if (player.chapter === "青棒" && Number(player.age) === 16) return true;
  const schoolContext = getSelectedHighSchoolContext(player);
  applyChapterBreather();
  player.chapter = "青棒";
  player.age = 16;
  player.highSchoolStep = 0;
  player.highSchoolPositionPreference = player.primaryPosition || "";
  player.highSchoolRoleCode = "";
  player.highSchoolCompetitionEvaluation = null;
  player.highSchoolOpportunityHistory = [];
  player.highSchoolNextOpportunity = null;
  player.highSchoolYearOneStartingRole = "";
  player.highSchoolYearOneMatchHistory = [];
  player.highSchoolYearOneComplete = false;
  player.highSchoolMatch = createInitialPlayer().highSchoolMatch;
  player.highSchoolAzheEcho = createInitialPlayer().highSchoolAzheEcho;
  player.highSchoolRivalContext = createInitialPlayer().highSchoolRivalContext;
  const schoolName = schoolContext?.schoolName || state.legacyExistingSchool?.schoolName || player.highSchoolRoute;
  showNotice(`你進入${schoolName}，高中棒球正式開始。`, "success");
  showCurrentEvent();
  return true;
}

function toMatchRoster(teamRoster, strengthProfile = null) {
  const byId = new Map(teamRoster.players.map(player => [player.playerId, player]));
  const lineup = teamRoster.battingOrder.map(slot => {
    const player = byId.get(slot.playerId);
    return Object.freeze({ ...player, id: player.id || player.playerId, position: POSITION_LABELS[slot.defensivePosition], defensivePosition: slot.defensivePosition, source: player.id === "player" ? "canonical-player" : "simulation-roster" });
  });
  const starterIds = new Set(lineup.map(player => player.playerId));
  const bench = teamRoster.benchPlayers.filter(player => !starterIds.has(player.playerId)).map(player => Object.freeze({ ...player, id: player.id || player.playerId, position: POSITION_LABELS[player.primaryPosition], source: player.id === "player" ? "canonical-player" : "simulation-roster" }));
  const roster = { lineup, bench, pitchingStaff: teamRoster.pitchingStaff, teamRoster, teamStrengthProfile: strengthProfile, source: VERSION };
  assertActiveDefense(roster);
  return roster;
}

function injectPlayerIntoRoster(baseRoster, playerActor, options = {}) {
  if (!validateRoster(baseRoster).ok) throw new Error("Player injection requires a valid base TeamRoster.");
  const actor = createPlayerActor(playerActor, baseRoster.teamId);
  const requestedPosition = normalizePosition(options.playerPosition || actor.primaryPosition);
  const starterRequested = options.playerRole === "starter";
  const starterAllowed = starterRequested && requestedPosition && isPositionEligible(actor, requestedPosition);
  const starters = baseRoster.starters.filter(player => player.id !== "player").slice();
  const benchPlayers = baseRoster.benchPlayers.filter(player => player.id !== "player").slice();
  let replacedPlayerId = "";
  if (starterAllowed) {
    const assignedStarterId = baseRoster.battingOrder?.find(slot => slot.defensivePosition === requestedPosition)?.playerId;
    const index = starters.findIndex(player => player.playerId === assignedStarterId);
    if (index >= 0) {
      const incumbent = starters[index];
      replacedPlayerId = incumbent.playerId;
      benchPlayers.push(incumbent);
      starters[index] = Object.freeze({ ...actor, primaryPosition: requestedPosition });
    } else benchPlayers.push(actor);
  } else benchPlayers.push(actor);
  const player = starters.find(item => item.id === "player") || benchPlayers.find(item => item.id === "player");
  const existingIds = new Set([...starters, ...benchPlayers].map(item => item.playerId));
  const players = [...baseRoster.players.filter(item => item.id !== "player" && existingIds.has(item.playerId)), player].filter(Boolean);
  const battingOrder = orderLineup(starters);
  const pitchingStaff = requestedPosition === "P" && starterAllowed && replacedPlayerId
    ? Object.freeze({ starter: player.playerId, secondaryPitchers: Object.freeze([replacedPlayerId, ...(baseRoster.pitchingStaff?.secondaryPitchers || []).filter(id => id !== replacedPlayerId)]) })
    : baseRoster.pitchingStaff;
  return Object.freeze({
    ...baseRoster,
    players: Object.freeze(players), starters: Object.freeze(starters), benchPlayers: Object.freeze(benchPlayers), battingOrder, pitchingStaff,
    playerInjection: Object.freeze({
      playerId: player?.playerId || "player", requestedPosition, assignedPosition: starterAllowed && replacedPlayerId ? requestedPosition : "",
      rosterRole: starterAllowed && replacedPlayerId ? "starter" : "bench", replacedPlayerId,
      legal: requestedPosition ? isHighSchoolPositionAssignmentLegal(actor, requestedPosition) : false
    })
  });
}

function resolvePlannedAppearance(score, role, coachStyle, hash) {
  if (score >= 55) return { appearanceType: "start", entryInning: 1, entryHalf: "上" };
  if (score < 36) return { appearanceType: "noAppearance", entryInning: null, entryHalf: "" };
  const entryInning = role === "rotation" ? 5 : 5 + (hash % 2);
  const appearanceSelector = hash % 10;
  const appearanceType = coachStyle === "developmental" || appearanceSelector <= 3
    ? "defensiveSubstitution"
    : appearanceSelector <= 6 ? "pinchHit" : "lateGameAppearance";
  return { appearanceType, entryInning, entryHalf: "下" };
}

function markSettled(situation, input = {}) {
  if (situation.lifecycleState === "settled" || situation.lifecycleState === "closed") return situation;
  return transition(situation, "settled", {
    settlement: { applied: true, identity: input.identity || `${situation.situationId}|settlement` }
  }, { phase: situation.phase, reason: "canonicalSettlementApplied" });
}

function closeSituation(situation, input = {}) {
  if (situation.lifecycleState === "closed") return situation;
  if (!situation.resolution || situation.settlement?.applied !== true
    || situation.reassessmentState?.requiresDecision === true || situation.executionState?.status === "inProgress") {
    throw new Error("match situation cannot close before resolution and settlement");
  }
  return transition(situation, "closed", {
    closeState: { reason: input.reason || "settlementComplete", readyToResume: true }
  }, { phase: situation.phase, reason: input.reason || "settlementComplete" });
}

function evaluateHighSchoolMatchDefensiveDecisionDensity(match, situation, legalChoices = [], classification = null) {
  const state = ensureHighSchoolMatchDecisionDensityState(match);
  const descriptor = createHighSchoolDefensiveNoveltyDescriptor(situation, legalChoices);
  const playIndex = Array.isArray(match?.simulationLog) ? match.simulationLog.length : 0;
  const spacing = state?.lastDecisionPlayIndex >= 0 ? playIndex - state.lastDecisionPlayIndex : Number.POSITIVE_INFINITY;
  const meaningfulCandidate = classification?.eventClassification === "playerMeaningfulDecision";
  const repeated = meaningfulCandidate && descriptor.noveltyKey === state?.lastNoveltyKey;
  const situationNovel = meaningfulCandidate && !state?.recentSituationFamilies.includes(descriptor.situationFamily);
  const routeNovel = meaningfulCandidate && !state?.recentRouteFamilies.includes(descriptor.routeFamily);
  let allowed = meaningfulCandidate;
  let suppressionReason = "";
  if (!meaningfulCandidate) {
    allowed = false;
    suppressionReason = "not-meaningful";
  } else if ((state?.defensiveMeaningfulDecisionCount || 0) >= 4 && !routeNovel) {
    allowed = false;
    suppressionReason = "route-family-density";
  } else if (repeated && spacing < MATCH_DECISION_REPEAT_SPACING) {
    allowed = false;
    suppressionReason = "repeated-situation-spacing";
  } else if ((state?.currentConsecutiveMeaningfulDecisions || 0) >= MATCH_DECISION_MAX_CONSECUTIVE && spacing <= 1) {
    allowed = false;
    suppressionReason = "decision-density-spacing";
  } else if ((state?.defensiveMeaningfulDecisionCount || 0) >= MATCH_DECISION_ABSOLUTE_SAFETY_CAP) {
    allowed = false;
    suppressionReason = "absolute-safety-cap";
  }
  return Object.freeze({
    version: MATCH_DECISION_DENSITY_VERSION,
    allowed,
    meaningfulCandidate,
    suppressionReason,
    playIndex,
    spacing: Number.isFinite(spacing) ? spacing : null,
    repeated,
    situationNovel,
    routeNovel,
    highNovelty: situationNovel || routeNovel,
    absoluteSafetyCap: MATCH_DECISION_ABSOLUTE_SAFETY_CAP,
    maxConsecutiveMeaningfulDecisions: MATCH_DECISION_MAX_CONSECUTIVE,
    ...descriptor
  });
}

