"use strict";
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const P=require('./match-admission-moment-eligibility-contract-v0.1-capture.cjs'),E=require('../tests/entry-safe-runner.cjs');
const prefix='docs/match-contract-separation-v0.1-',report='docs/match-contract-separation-v0.1.md',childPrefix='docs/test-infrastructure-sprint-0.1-match-contract-separation-v0.1-';
const isNew=p=>p===report||p.startsWith(prefix)||p.startsWith(childPrefix);
function capture(label,data){assert(/^[a-z0-9-]+$/.test(label));const p=prefix+label+'-evidence.json';assert(!fs.existsSync(path.join(P.root,p)),p);fs.writeFileSync(path.join(P.root,p),JSON.stringify({task:'Match Contract Separation v0.1 — Acceptance Design & Isolated Proof',createdAt:new Date().toISOString(),...data},null,2)+'\n',{flag:'wx'});return p;}
function baseline(){const b=P.json(P.prefix+'baseline-evidence.json'),d=P.json(P.prefix+'delivery-evidence.json'),c=P.json(P.prefix+'closeout-evidence.json');
 for(const [p,h] of Object.entries(b.hashes))assert.equal(P.fileHash(p),h,p);for(const [p,h] of Object.entries(d.hashes))assert.equal(P.fileHash(p),h,p);
 const git=P.gitState();assert.equal(git.branch,'main');assert.equal(git.index,'');for(const k of ['head','main','originMain'])assert.equal(git[k],'ab3117653945de0b7013636187c446276a96e634');
 assert.deepEqual(P.metadata(),b.protectedMetadata);const finals=new Set([P.prefix+'closeout-evidence.json',P.prefix+'delivery-evidence.json']);const status=s=>s.split(/\r?\n/).filter(l=>l&&!isNew(l.slice(3))&&!finals.has(l.slice(3))).sort();assert.deepEqual(status(git.status),status(c.git.status));
 const files=P.files().filter(p=>!isNew(p)),allowed=new Set([...Object.keys(b.hashes),...d.files,P.prefix+'delivery-evidence.json']);assert.deepEqual(files.filter(p=>!allowed.has(p)),[]);
 const hashes=Object.fromEntries(files.map(p=>[p,P.fileHash(p)]));capture('baseline',{git,hashes,readableExistingFiles:files.length,priorBaselineVerified:Object.keys(b.hashes).length,priorDeliveryVerified:Object.keys(d.hashes).length,priorDelivery:{path:P.prefix+'delivery-evidence.json',sha256:P.fileHash(P.prefix+'delivery-evidence.json')},priorFinalBookkeepingAccounted:[...finals],protectedMetadata:P.metadata(),protectedContentReadOrHashed:false,remoteServerRechecked:false,productionFormalTestFixtureSeedPinEditsAuthorized:false});console.log(JSON.stringify({baseline:'VERIFIED',readableExistingFiles:files.length,protectedPaths:P.protectedPaths.size,indexEmpty:true}));}
function integrity(){const b=P.json(prefix+'baseline-evidence.json');for(const [p,h] of Object.entries(b.hashes))assert.equal(P.fileHash(p),h,p);assert.deepEqual(P.metadata(),b.protectedMetadata);const git=P.gitState();for(const k of ['branch','head','main','originMain','index'])assert.equal(git[k],b.git[k]);const status=s=>s.split(/\r?\n/).filter(l=>l&&!isNew(l.slice(3))).sort();assert.deepEqual(status(git.status),status(b.git.status));assert.deepEqual(P.files().filter(p=>!(p in b.hashes)&&!isNew(p)),[]);return{preservedExistingHashes:Object.keys(b.hashes).length,changedExistingPaths:[],productionDelta:0,formalTestDelta:0,existingFixtureSeedPinDelta:0,protectedMetadataUnchanged:true,protectedContentReadOrHashed:false,git};}
function run(label,file,extra=[]){integrity();const b=P.json(prefix+'baseline-evidence.json'),relevant=Object.keys(b.hashes).filter(p=>!p.startsWith('docs/')&&/\.(js|cjs|json|html)$/.test(p));const row=E.runSuite({suiteName:label,file,entryMode:'standalone',evidencePath:childPrefix+label+'-evidence.json',relevantPaths:[...relevant,prefix+'capture.cjs',...extra]});integrity();console.log(JSON.stringify({label,status:row.status,exitCode:row.exitCode,elapsedMs:row.elapsedMs,entryVerified:row.entryVerified,sourceStable:row.sourceStable,summary:row.stdout.split(/\r?\n/).filter(l=>l.includes('_SUMMARY=')),stderr:row.stderr}));return row;}
module.exports={...P,prefix,report,childPrefix,isNew,capture,integrity,run};
if(require.main===module){if(process.argv[2]==='baseline')baseline();else throw Error('Explicit baseline required');}

"use strict";
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const C=require('./match-contract-separation-v0.1-capture.cjs');
C.integrity();
const read=p=>fs.readFileSync(path.join(C.root,p),'utf8'),graph=C.json(C.prefix+'architecture-coverage-evidence.json');
function unwrap(r){if(r.status==='fulfilled')r=r.value;assert(!r.isError);return r.structuredContent||JSON.parse(r.content.find(c=>c.type==='text').text);}
function verifySnippet(s,symbol){const p=(s.file_path||s.path).replaceAll('\\','/').replace(C.root.replaceAll('\\','/')+'/',''),a=s.start_line||s.startLine,b=s.end_line||s.endLine;
 const current=read(p).split(/\r?\n/).slice(a-1,b).join('\n')+'\n';assert.equal(current,s.source.replace(/\r\n/g,'\n'),symbol||s.symbol);return{symbol:symbol||s.symbol,path:p,startLine:a,endLine:b,source:current,sha256:C.fileHash(p),currentLinesVerified:true};}
